/// <summary>
/// Extension of formDatasource PriceDiscGroup in form PriceDiscGroup
/// </summary>
[ExtensionOf(formDataSourceStr(PriceDiscGroup, PriceDiscGroup))]
final class AVAPriceDiscGroupFrm_PriceDiscGroup_Extension
{
}

Method.Source:
/// <summary>
/// Extension of active method
/// </summary>
/// <returns>int</returns>
public int active()
{
    int ret = next active();

    switch (element.priceDiscGroup.Type)
    {
        case PriceGroupType::PriceGroup :
            element.avaEnablePriceListButton(true);
            break;

        default:
            element.avaEnablePriceListButton(false);
            break;
    }

    return ret;
}
